-- V4.1 additive legal, contradictory-procedure, franchise-governance, marketing-security and catalogue-review records.

create table public.contract_authority_snapshots(
 id uuid primary key default extensions.gen_random_uuid(),contract_id uuid not null references public.contracts(id)on delete restrict,contract_version_id uuid not null references public.contract_versions(id)on delete restrict,organization_id uuid not null references public.organizations(id)on delete restrict,signer_user_id uuid not null references auth.users(id),authority_type text not null check(authority_type in('LEGAL_REPRESENTATIVE','DELEGATION','POWER_OF_ATTORNEY')),authority_reference text not null,authority_evidence_hash text not null check(authority_evidence_hash~'^[0-9a-f]{64}$'),verified_by uuid not null references auth.users(id),verified_at timestamptz not null,valid_from timestamptz not null,valid_until timestamptz,created_at timestamptz not null default clock_timestamp(),foreign key(contract_version_id,contract_id)references public.contract_versions(id,contract_id)on delete restrict,check(valid_until is null or valid_until>valid_from),unique(contract_version_id,organization_id,signer_user_id,authority_evidence_hash)
);
create table public.contract_lifecycle_terms(
 id uuid primary key default extensions.gen_random_uuid(),contract_id uuid not null references public.contracts(id)on delete restrict,contract_version_id uuid not null unique references public.contract_versions(id)on delete restrict,effective_at timestamptz not null,expires_at timestamptz,renewal_mode text not null check(renewal_mode in('NONE','MANUAL','AUTOMATIC')),renewal_notice_days integer not null default 0 check(renewal_notice_days between 0 and 730),suspension_terms jsonb not null check(jsonb_typeof(suspension_terms)='object'),termination_terms jsonb not null check(jsonb_typeof(termination_terms)='object'),document_priority jsonb not null check(jsonb_typeof(document_priority)='array'and jsonb_array_length(document_priority)>0),clauses_version text not null,legal_hold_required boolean not null default false,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),foreign key(contract_version_id,contract_id)references public.contract_versions(id,contract_id)on delete restrict,check(expires_at is null or expires_at>effective_at)
);
create table public.contract_annex_versions(
 id uuid primary key default extensions.gen_random_uuid(),contract_id uuid not null references public.contracts(id)on delete restrict,contract_version_id uuid not null references public.contract_versions(id)on delete restrict,annex_key text not null check(annex_key~'^[A-Z][A-Z0-9_.-]{1,79}$'),version integer not null check(version>0),priority integer not null check(priority>0),title_fr text not null,title_ar text not null,document_hash text not null check(document_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),foreign key(contract_version_id,contract_id)references public.contract_versions(id,contract_id)on delete restrict,unique(contract_version_id,annex_key,version),unique(contract_version_id,priority)
);
create table public.contract_obligation_definitions(
