revoke all on private.catalog_review_command_keys from public,anon,authenticated,service_role;

create function private.prevent_v41_legal_history_change()returns trigger language plpgsql set search_path=pg_catalog as $$begin raise exception'V41_HISTORY_IMMUTABLE'using errcode='55000';end$$;
create function private.capture_dispute_opening_snapshot_v41()returns trigger language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare q_hash text;d_hash text;c_hash text;m_hash text;manifest jsonb;hold_hash text;begin
 select private.canonical_request_hash(v.quote_snapshot)into q_hash from public.contract_versions v where v.id=new.contract_version_id;
 select private.canonical_request_hash(coalesce(jsonb_agg(jsonb_build_object('delivery_version_id',v.id,'content_hash',v.content_hash)order by v.id),'[]'::jsonb))into d_hash from public.delivery_versions v join public.deliverables d on d.id=v.deliverable_id where d.mission_id=new.mission_id;
 select private.canonical_request_hash(coalesce(jsonb_agg(jsonb_build_object('item_id',i.id,'status',i.status,'completed_at',i.completed_at)order by i.id),'[]'::jsonb))into c_hash from public.mission_checklist_items i where i.mission_id=new.mission_id;
 select private.canonical_request_hash(coalesce(jsonb_agg(jsonb_build_object('message_id',msg.id,'version',msg.version,'created_at',msg.created_at)order by msg.id),'[]'::jsonb))into m_hash from public.internal_messages msg join public.internal_message_threads t on t.id=msg.thread_id where t.object_id in(select q.rfq_id from public.contract_versions cv join public.quote_versions qv on qv.id=cv.selected_quote_version_id join public.quotes q on q.id=qv.quote_id where cv.id=new.contract_version_id);
 manifest:=jsonb_build_object('contract_version_id',new.contract_version_id,'mission_id',new.mission_id,'captured_at',clock_timestamp(),'quote_hash',q_hash,'delivery_hash',d_hash,'checklist_hash',c_hash,'message_hash',m_hash);
 insert into public.dispute_opening_snapshots(dispute_case_id,contract_version_id,quote_snapshot_hash,delivery_snapshot_hash,checklist_snapshot_hash,message_manifest_hash,snapshot_manifest,created_by)values(new.id,new.contract_version_id,q_hash,d_hash,c_hash,m_hash,manifest,new.opened_by);
 hold_hash:=private.canonical_request_hash(manifest);
 insert into public.legal_evidence_holds(dispute_case_id,hold_version,decision,reason,scope_manifest_hash,decided_by)values(new.id,1,'APPLIED','Gel automatique des preuves au moment exact de l ouverture du litige.',hold_hash,new.opened_by);
 return new;end$$;
create trigger v41_dispute_opening_snapshot after insert on public.dispute_cases for each row execute function private.capture_dispute_opening_snapshot_v41();
create function private.marketing_publication_ready_v41(p_organization_id uuid,p_provider text,p_connection_id uuid,p_content_version_id uuid)returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
 select private.marketing_consent_active(p_organization_id,'SOCIAL_PUBLISHING')
 and exists(select 1 from public.social_connections c where c.id=p_connection_id and c.organization_id=p_organization_id and c.provider=p_provider and c.status='ACTIVE')
 and coalesce((select decision='GRANTED'and effective_from<=clock_timestamp()and(effective_until is null or effective_until>clock_timestamp())from public.marketing_brand_authorizations where organization_id=p_organization_id order by decided_at desc,id desc limit 1),false)
 and coalesce((select status='ACTIVE'and(expires_at is null or expires_at>clock_timestamp())and case when p_provider='LINKEDIN'then approved_scopes@>array['w_member_social']::text[]when p_provider='META'then approved_scopes@>array['pages_manage_posts']::text[]else false end from public.social_connection_security_versions where social_connection_id=p_connection_id order by version desc limit 1),false)
 and exists(select 1 from public.marketing_content_versions v join public.marketing_content mc on mc.id=v.content_id join public.marketing_campaigns campaign on campaign.id=mc.campaign_id where v.id=p_content_version_id and campaign.organization_id=p_organization_id and campaign.status in('APPROVED','SCHEDULED','PUBLISHED')and v.status='APPROVED'and(v.expires_at is null or v.expires_at>clock_timestamp())and v.compliance_checks?&array['offer','price','certification','privacy','pii']and not exists(select 1 from jsonb_each_text(v.compliance_checks)q where q.value<>'PASS'))
 and not coalesce((select enabled from public.marketing_kill_switch_versions where organization_id is null and scope='GLOBAL'order by version desc limit 1),false)
 and not coalesce((select enabled from public.marketing_kill_switch_versions where organization_id is null and scope='PROVIDER'and provider=p_provider order by version desc limit 1),false)
 and not coalesce((select enabled from public.marketing_kill_switch_versions where organization_id=p_organization_id and scope='GLOBAL'order by version desc limit 1),false)
 and not coalesce((select enabled from public.marketing_kill_switch_versions where organization_id=p_organization_id and scope='PROVIDER'and provider=p_provider order by version desc limit 1),false)
$$;

