ct_hash',p_subject_hash,'notice_type',p_notice_type,'attachments',p_attachments));cached:=private.begin_contract_command(sender,'contract.notice.record.'||c.id::text,p_idempotency_key,h,a);if cached is not null then return cached;end if;insert into public.probative_notices(contract_id,contract_version_id,notice_type,template_key,template_version,sender_organization_id,recipient_organization_id,recipient_address_hash,subject_hash,channel,evidence_level,provider_message_id,document_hash,attachments,sent_by,correlation_id,idempotency_key)values(c.id,v,p_notice_type,p_template_key,p_template_version,sender,p_recipient_organization_id,p_recipient_address_hash,p_subject_hash,p_channel,p_evidence_level,p_provider_message_id,p_document_hash,p_attachments,a,p_correlation_id,p_idempotency_key)returning id into n;r:=jsonb_build_object('outcome','PROBATIVE_NOTICE_RECORDED','notice_id',n,'evidence_level',p_evidence_level);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(sender,a,'USER','contract.notice.recorded','probative_notice',n::text,p_correlation_id,jsonb_build_object('contract_id',c.id,'notice_type',p_notice_type,'evidence_level',p_evidence_level),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(sender,'contract',c.id::text,'ContractProbativeNoticeRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(sender,'contract.notice.record.'||c.id::text,p_idempotency_key,r);return r;end$$;

create function public.record_dispute_governance_v41(p_dispute_case_id uuid,p_action text,p_payload jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();d public.dispute_cases%rowtype;h text;cached jsonb;r jsonb;x uuid;prior public.legal_evidence_holds%rowtype;v integer;assignment public.dispute_reviewer_assignments%rowtype;begin select*into d from public.dispute_cases where id=p_dispute_case_id;if a is null or not found or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','DISPUTE_MANAGER'],a)then raise exception'DISPUTE_GOVERNANCE_DENIED'using errcode='42501';end if;if p_action not in('APPLY_HOLD','RELEASE_HOLD','DISCLOSE_CONFLICT','APPEAL_REVIEW')or jsonb_typeof(p_payload)<>'object'then raise exception'INVALID_DISPUTE_GOVERNANCE_ACTION'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('case',d.id,'action',p_action,'payload',p_payload));cached:=private.begin_contract_command(d.client_organization_id,'dispute.governance.'||d.id::text||'.'||lower(p_action),p_idempotency_key,h,a);if cached is not null then return cached;end if;if p_action in('APPLY_HOLD','RELEASE_HOLD')then select*into prior from public.legal_evidence_holds where dispute_case_id=d.id order by hold_version desc limit 1;if p_action='APPLY_HOLD'and prior.decision='APPLIED'or p_action='RELEASE_HOLD'and(coalesce(prior.decision,'')<>'APPLIED')then raise exception'INVALID_LEGAL_HOLD_TRANSITION'using errcode='55000';end if;if not(p_payload?&array['reason','scope_manifest_hash'])or p_payload->>'scope_manifest_hash'!~'^[0-9a-f]{64}$'or length(btrim(p_payload->>'reason'))<10 then raise exception'INVALID_LEGAL_HOLD'using errcode='22023';end if;v:=coalesce(prior.hold_version,0)+1;insert into public.legal_evidence_holds(dispute_case_id,hold_version,decision,reason,scope_manifest_hash,supersedes_hold_id,decided_by)values(d.id,v,case when p_action='APPLY_HOLD'then'APPLIED'else'RELEASED'end,p_payload->>'reason',p_payload->>'scope_manifest_hash',case when p_action='RELEASE_HOLD'then prior.id end,a)returning id into x;elsif p_action='DISCLOSE_CONFLICT'then if not(p_payload?&array['reviewer_user_id','decision','reason','evidence_hash'])or p_payload->>'decision'not in('NO_CONFLICT_DECLARED','CONFLICT_DECLARED','RECUSED')or p_payload->>'evidence_hash'!~'^[0-9a-f]{64}$'then raise exception'INVALID_DISPUTE_CONFLICT_DISCLOSURE'using errcode='22023';end if;insert into public.dispute_conflict_disclosures(dispute_case_id,reviewer_user_id,decision,reason,evidence_hash,declared_by)values(d.id,(p_payload->>'reviewer_user_id')::uuid,p_payload->>'decision',p_payload->>'reason',p_payload->>'evidence_hash',a)returning id into x;else if not(p_payload?&array['appeal_id','assignment_id','outcome','reason','evidence_ids','rule_snapshot'])or p_payload->>'outcome'not in('UPHELD','REVERSED','REMANDED')or jsonb_typeof(p_payload->'evidence_ids')<>'array'or jsonb_array_length(p_payload->'evidence_ids')=0 then raise exception'INVALID_DISPUTE_APPEAL_REVIEW'using errcode='22023';end if;select*into assignment from public.dispute_reviewer_assignments where id=(p_payload->>'assignment_id')::uuid and dispute_case_id=d.id;if not found or assignment.reviewer_user_id<>a or assignment.assignment_type<>'APPEAL_REVIEW'or assignment.status<>'ASSIGNED'or exists(select 1 from public.dispute_conflict_disclosures where dispute_case_id=d.id and reviewer_user_id=a and decision in('CONFLICT_DECLARED','RECUSED'))then raise exception'DISPUTE_APPEAL_REVIEWER_INVALID'using errcode='42501';end if;insert into public.dispute_appeal_reviews(dispute_case_id,appeal_id,assignment_id,outcome,reason,evidence_ids,rule_snapshot,decided_by)select d.id,(p_payload->>'appeal_id')::uuid,assignment.id,p_payload->>'outcome',p_payload->>'reason',array(select jsonb_array_elements_text(p_payload->'evidence_ids')::uuid),p_payload->'rule_snapshot',a returning id into x;end if;r:=jsonb_build_object('outcome','DISPUTE_GOVERNANCE_RECORDED','dispute_case_id',d.id,'action',p_action,'record_id',x);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(d.client_organization_id,a,'USER','dispute.governance.'||lower(p_action),'dispute_case',d.id::text,p_correlation_id,jsonb_build_object('action',p_action,'record_id',x),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(d.client_organization_id,'dispute_case',d.id::text,'DisputeGovernanceRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(d.client_organization_id,'dispute.governance.'||d.id::text||'.'||lower(p_action),p_idempotency_key,r);return r;exception when invalid_text_representation then raise exception'INVALID_DISPUTE_GOVERNANCE_ACTION'using errcode='22023';end$$;

create function public.assign_dispute_reviewer_v41(p_dispute_case_id uuid,p_reviewer_user_id uuid,p_assignment_type text,p_no_conflict_evidence_hash text,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();d public.dispute_cases%rowtype;h text;cached jsonb;r jsonb;x uuid;begin select*into d from public.dispute_cases where id=p_dispute_case_id;if a is null or not found or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','DISPUTE_MANAGER'],a)then raise exception'DISPUTE_REVIEWER_ASSIGN_DENIED'using errcode='42501';end if;if p_assignment_type not in('MEDIATION','DECISION_REVIEW','APPEAL_REVIEW')or p_reviewer_user_id=a or p_no_conflict_evidence_hash!~'^[0-9a-f]{64}$'or length(btrim(p_reason))<10 or exists(select 1 from public.dispute_conflict_disclosures where dispute_case_id=d.id and reviewer_user_id=p_reviewer_user_id and decision in('CONFLICT_DECLARED','RECUSED'))then raise exception'DISPUTE_REVIEWER_CONFLICT'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('case',d.id,'reviewer',p_reviewer_user_id,'type',p_assignment_type,'evidence',p_no_conflict_evidence_hash,'reason',p_reason));cached:=private.begin_contract_command(d.client_organization_id,'dispute.reviewer.assign.'||d.id::text,p_idempotency_key,h,a);if cached is not null then return cached;end if;insert into public.dispute_reviewer_assignments(dispute_case_id,reviewer_user_id,assignment_type,status,no_conflict_evidence_hash,assigned_by)values(d.id,p_reviewer_user_id,p_assignment_type,'ASSIGNED',p_no_conflict_evidence_hash,a)returning id into x;r:=jsonb_build_object('outcome','HUMAN_REVIEWER_ASSIGNED','assignment_id',x,'dispute_case_id',d.id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(d.client_organization_id,a,'USER','dispute.reviewer.assigned','dispute_case',d.id::text,p_correlation_id,jsonb_build_object('assignment_id',x,'assignment_type',p_assignment_type),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(d.client_organization_id,'dispute_case',d.id::text,'DisputeHumanReviewerAssignedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(d.client_organization_id,'dispute.reviewer.assign.'||d.id::text,p_idempotency_key,r);return r;end$$;

create function public.record_franchise_governance_control_v41(p_franchise_id uuid,p_action text,p_payload jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();f public.franchises%rowtype;h text;cached jsonb;r jsonb;x uuid;event_id bigint;proposer uuid;begin select*into f from public.franchises where id=p_franchise_id;if a is null or not found or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],a)then raise exception'FRANCHISE_GOVERNANCE_CONTROL_DENIED'using errcode='42501';end if;if p_action not in('EVIDENCE','FAVORITISM_REVIEW','CORRECTIVE_PLAN_VERSION','CORRECTIVE_PLAN_EVENT')or jsonb_typeof(p_payload)<>'object'then raise exception'INVALID_FRANCHISE_GOVERNANCE_CONTROL'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('franchise',f.id,'action',p_action,'payload',p_payload));cached:=private.begin_contract_command(f.operator_organization_id,'franchise.governance.control.'||f.id::text||'.'||lower(p_action),p_idempotency_key,h,a);if cached is not null then return cached;end if;if p_action='EVIDENCE'then if not(p_payload?&array['evidence_type','period_start','period_end','evidence_hash','evidence_manifest'])then raise exception'INVALID_FRANCHISE_GOVERNANCE_EVIDENCE'using errcode='22023';end if;insert into public.franchise_governance_evidence(franchise_id,evidence_type,period_start,period_end,evidence_hash,evidence_manifest,recorded_by)values(f.id,p_payload->>'evidence_type',(p_payload->>'period_start')::date,(p_payload->>'period_end')::date,p_payload->>'evidence_hash',p_payload->'evidence_manifest',a)returning id into x;elsif p_action='FAVORITISM_REVIEW'then if not(p_payload?&array['period_start','period_end','rule_version','provider_distribution_snapshot','risk_level','outcome','evidence_hash'])then raise exception'INVALID_FRANCHISE_FAVORITISM_REVIEW'using errcode='22023';end if;insert into public.franchise_favoritism_reviews(franchise_id,period_start,period_end,rule_version,provider_distribution_snapshot,risk_level,outcome,evidence_hash,reviewed_by)values(f.id,(p_payload->>'period_start')::date,(p_payload->>'period_end')::date,p_payload->>'rule_version',p_payload->'provider_distribution_snapshot',p_payload->>'risk_level',p_payload->>'outcome',p_payload->>'evidence_hash',a)returning id into x;elsif p_action='CORRECTIVE_PLAN_VERSION'then if not(p_payload?&array['plan_key','version','status','objectives','actions','due_on','content_hash','proposed_by'])then raise exception'INVALID_FRANCHISE_CORRECTIVE_PLAN'using errcode='22023';end if;proposer:=(p_payload->>'proposed_by')::uuid;if p_payload->>'status'<>'PROPOSED'and proposer=a then raise exception'FRANCHISE_FOUR_EYES_REQUIRED'using errcode='42501';end if;insert into public.franchise_corrective_plan_versions(franchise_id,plan_key,version,status,objectives,actions,due_on,requires_human_decision,content_hash,supersedes_version_id,created_by,approved_by)values(f.id,p_payload->>'plan_key',(p_payload->>'version')::integer,p_payload->>'status',p_payload->'objectives',p_payload->'actions',(p_payload->>'due_on')::date,true,p_payload->>'content_hash',nullif(p_payload->>'supersedes_version_id','')::uuid,proposer,case when p_payload->>'status'='PROPOSED'then null else a end)returning id into x;else if not(p_payload?&array['plan_version_id','event_type','reason'])then raise exception'INVALID_FRANCHISE_CORRECTIVE_PLAN_EVENT'using errcode='22023';end if;if not exists(select 1 from public.franchise_corrective_plan_versions p where p.id=(p_payload->>'plan_version_id')::uuid and p.franchise_id=f.id)then raise exception'FRANCHISE_PLAN_NOT_FOUND'using errcode='P0002';end if;insert into public.franchise_corrective_plan_events(plan_version_id,event_type,reason,evidence_hash,actor_user_id,correlation_id)values((p_payload->>'plan_version_id')::uuid,p_payload->>'event_type',p_payload->>'reason',nullif(p_payload->>'evidence_hash',''),a,p_correlation_id)returning id into event_id;x:=null;end if;r:=jsonb_build_object('outcome','FRANCHISE_GOVERNANCE_CONTROL_RECORDED','franchise_id',f.id,'action',p_action,'record_id',x,'event_id',event_id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(f.operator_organization_id,a,'USER','franchise.governance.'||lower(p_action),'franchise',f.id::text,p_correlation_id,jsonb_build_object('action',p_action,'record_id',x,'event_id',event_id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(f.operator_organization_id,'franchise',f.id::text,'FranchiseGovernanceControlRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(f.operator_organization_id,'franchise.governance.control.'||f.id::text||'.'||lower(p_action),p_idempotency_key,r);return r;exception when invalid_text_representation then raise exception'INVALID_FRANCHISE_GOVERNANCE_CONTROL'using errcode='22023';end$$;

create function public.set_marketing_kill_switch_v41(p_organization_id uuid,p_scope text,p_provider text,p_enabled boolean,p_reason text,p_evidence_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();h text;r jsonb;x uuid;v integer;prior public.marketing_kill_switch_versions%rowtype;begin if a is null or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],a)then raise exception'MARKETING_KILL_SWITCH_DENIED'using errcode='42501';end if;if p_scope not in('GLOBAL','PROVIDER')or(p_scope='GLOBAL'and p_provider is not null)or(p_scope='PROVIDER'and p_provider not in('LINKEDIN','META'))or length(btrim(p_reason))<3 or p_evidence_hash!~'^[0-9a-f]{64}$'or length(coalesce(p_idempotency_key,''))not between 8 and 200 then raise exception'INVALID_MARKETING_KILL_SWITCH'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'scope',p_scope,'provider',p_provider,'enabled',p_enabled,'reason',p_reason,'evidence',p_evidence_hash));perform pg_advisory_xact_lock(hashtextextended('marketing-kill-switch-scope:'||coalesce(p_organization_id::text,'PLATFORM')||':'||p_scope||':'||coalesce(p_provider,'ALL'),0));select*into prior from public.marketing_kill_switch_versions where idempotency_key=p_idempotency_key;if found then if prior.request_hash<>h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome',case when prior.enabled then'MARKETING_KILL_SWITCH_ENABLED'else'MARKETING_KILL_SWITCH_DISABLED'end,'kill_switch_version_id',prior.id,'scope',prior.scope,'provider',prior.provider);end if;select coalesce(max(version),0)+1 into v from public.marketing_kill_switch_versions where organization_id is not distinct from p_organization_id and scope=p_scope and provider is not distinct from p_provider;insert into public.marketing_kill_switch_versions(organization_id,scope,provider,version,enabled,reason,evidence_hash,idempotency_key,request_hash,decided_by)values(p_organization_id,p_scope,p_provider,v,p_enabled,p_reason,p_evidence_hash,p_idempotency_key,h,a)returning id into x;if p_enabled then update public.social_publication_jobs set status='SKIPPED'where status='QUEUED'and(p_organization_id is null or organization_id=p_organization_id)and(p_provider is null or provider=p_provider);end if;r:=jsonb_build_object('outcome',case when p_enabled then'MARKETING_KILL_SWITCH_ENABLED'else'MARKETING_KILL_SWITCH_DISABLED'end,'kill_switch_version_id',x,'scope',p_scope,'provider',p_provider);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','marketing.kill_switch.changed','marketing_kill_switch',x::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'marketing_kill_switch',x::text,'MarketingKillSwitchChangedV1',p_correlation_id,r,p_idempotency_key);return r;end$$;

create function public.claim_social_publication_job_v41(p_job_id uuid,p_worker_id text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();j public.social_publication_jobs%rowtype;c uuid;r jsonb;begin if a is null or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],a)or length(btrim(p_worker_id))not between 3 and 100 then raise exception'MARKETING_JOB_CLAIM_DENIED'using errcode='42501';end if;select*into j from public.social_publication_jobs where id=p_job_id for update;if not found or j.status<>'QUEUED'or j.available_at>clock_timestamp()then raise exception'MARKETING_JOB_NOT_CLAIMABLE'using errcode='55000';end if;select i.social_connection_id into c from public.marketing_calendar_items i where i.id=j.calendar_item_id;if not private.marketing_publication_ready_v41(j.organization_id,j.provider,c)then raise exception'MARKETING_PUBLICATION_BLOCKED'using errcode='55000';end if;update public.social_publication_jobs set status='CLAIMED',attempt_count=attempt_count+1 where id=j.id;r:=jsonb_build_object('outcome','SOCIAL_PUBLICATION_JOB_CLAIMED','job_id',j.id,'worker_id',p_worker_id,'attempt',j.attempt_count+1);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(j.organization_id,a,'USER','marketing.publication.claimed','social_publication_job',j.id::text,p_correlation_id,jsonb_build_object('provider',j.provider,'attempt',j.attempt_count+1),repeat('0',64));return r;end$$;

create function public.record_social_publication_result_v41(p_job_id uuid,p_outcome text,p_provider_publication_id text,p_error_code text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();j public.social_publication_jobs%rowtype;i public.marketing_calendar_items%rowtype;v public.marketing_content_versions%rowtype;prior public.social_publication_results%rowtype;auth_hash text;consent_hash text;r jsonb;begin if a is null or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],a)then raise exception'MARKETING_PUBLICATION_RESULT_DENIED'using errcode='42501';end if;if p_outcome not in('PUBLISHED','RETRYABLE_FAILURE','PERMANENT_FAILURE')or length(coalesce(p_idempotency_key,''))not between 8 and 200 or(p_outcome='PUBLISHED')<>(p_provider_publication_id is not null)or(p_outcome='PUBLISHED'and p_error_code is not null)then raise exception'INVALID_MARKETING_PUBLICATION_RESULT'using errcode='22023';end if;select*into j from public.social_publication_jobs where id=p_job_id for update;if not found then raise exception'MARKETING_JOB_NOT_FOUND'using errcode='P0002';end if;select*into prior from public.social_publication_results where job_id=j.id and attempt=j.attempt_count;if found then if prior.outcome<>p_outcome or prior.provider_publication_id is distinct from p_provider_publication_id or prior.error_code is distinct from p_error_code then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome',prior.outcome,'job_id',j.id,'attempt',prior.attempt);end if;if j.status<>'CLAIMED'then raise exception'MARKETING_JOB_NOT_CLAIMED'using errcode='55000';end if;select*into i from public.marketing_calendar_items where id=j.calendar_item_id;select*into v from public.marketing_content_versions where id=i.content_version_id;if p_outcome='PUBLISHED'and not private.marketing_publication_ready_v41(j.organization_id,j.provider,i.social_connection_id,i.content_version_id)then raise exception'MARKETING_PUBLICATION_BLOCKED'using errcode='55000';end if;insert into public.social_publication_results(job_id,attempt,outcome,provider_publication_id,error_code)values(j.id,j.attempt_count,p_outcome,p_provider_publication_id,p_error_code);if p_outcome='PUBLISHED'then select evidence_hash into auth_hash from public.marketing_brand_authorizations where organization_id=j.organization_id and decision='GRANTED'order by decided_at desc,id desc limit 1;select evidence_hash into consent_hash from public.marketing_consents where organization_id=j.organization_id and purpose='SOCIAL_PUBLISHING'and decision='GRANTED'order by decided_at desc,id desc limit 1;insert into public.marketing_publication_journal(organization_id,job_id,content_version_id,provider,provider_publication_id,content_snapshot,content_hash,authorization_evidence_hash,consent_evidence_hash,published_at)values(j.organization_id,j.id,v.id,j.provider,p_provider_publication_id,jsonb_build_object('language',v.language,'hook',v.hook,'body',v.body,'cta',v.cta,'hashtags',v.hashtags,'landing_url',v.landing_url),v.content_hash,auth_hash,consent_hash,clock_timestamp());update public.social_publication_jobs set status='PUBLISHED'where id=j.id;update public.marketing_calendar_items set status='PUBLISHED'where id=i.id;r:=jsonb_build_object('outcome','PUBLISHED','job_id',j.id,'provider_publication_id',p_provider_publication_id);else update public.social_publication_jobs set status=case when p_outcome='RETRYABLE_FAILURE'then'FAILED'else'FAILED'end where id=j.id;update public.marketing_calendar_items set status='FAILED'where id=i.id;r:=jsonb_build_object('outcome',p_outcome,'job_id',j.id,'error_code',p_error_code);end if;insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(j.organization_id,a,'USER','marketing.publication.result_recorded','social_publication_job',j.id::text,p_correlation_id,jsonb_build_object('outcome',p_outcome,'attempt',j.attempt_count),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(j.organization_id,'social_publication_job',j.id::text,case when p_outcome='PUBLISHED'then'SocialPublicationRecordedV1'else'SocialPublicationFailedV1'end,p_correlation_id,r,p_idempotency_key);return r;end$$;

do $$declare t text;begin foreach t in array array['contract_authority_snapshots','contract_lifecycle_terms','contract_annex_versions','contract_obligation_definitions','contract_obligation_events','probative_notices','probative_notice_delivery_events','contract_lifecycle_events','dispute_opening_snapshots','legal_evidence_holds','dispute_conflict_disclosures','dispute_reviewer_assignments','dispute_appeal_reviews','franchise_governance_evidence','franchise_catalog_change_evidence','franchise_conflict_disclosures','franchise_favoritism_reviews','franchise_corrective_plan_versions','franchise_corrective_plan_events','marketing_brand_authorizations','social_connection_security_versions','marketing_kill_switch_versions','marketing_publication_journal','catalog_content_review_findings']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('create trigger %I before update or delete on public.%I for each row execute function private.prevent_v41_legal_history_change()', 'v41_'||t||'_immutable',t);end loop;end$$;

