create policy marketing_brand_authorizations_scoped_read on public.marketing_brand_authorizations for select to authenticated using(private.marketing_manage_access(organization_id)or private.has_platform_role(array['READ_ONLY_AUDITOR']));
create policy marketing_connection_security_scoped_read on public.social_connection_security_versions for select to authenticated using(private.marketing_manage_access(organization_id)or private.has_platform_role(array['READ_ONLY_AUDITOR']));
create policy marketing_kill_switches_central_read on public.marketing_kill_switch_versions for select to authenticated using(private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','READ_ONLY_AUDITOR'])or(organization_id is not null and private.marketing_manage_access(organization_id)));
create policy marketing_publication_journal_scoped_read on public.marketing_publication_journal for select to authenticated using(private.marketing_manage_access(organization_id)or private.has_platform_role(array['READ_ONLY_AUDITOR']));
create policy catalog_content_review_central_read on public.catalog_content_review_findings for select to authenticated using(private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','LIBRARY_MANAGER','READ_ONLY_AUDITOR']));

