create function public.record_catalog_content_review_findings_v41(p_catalog_version text,p_source_manifest_hash text,p_findings jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions,auth as $$
declare a uuid:=auth.uid();service_call boolean:=coalesce(auth.role()='service_role',false);h text;prior private.catalog_review_command_keys%rowtype;r jsonb;run_id uuid:=extensions.gen_random_uuid();x jsonb;n integer:=0;begin if not(service_call or(a is not null and private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','LIBRARY_MANAGER'],a)))then raise exception'CATALOG_REVIEW_PERSIST_DENIED'using errcode='42501';end if;if p_catalog_version!~'^[0-9]+\.[0-9]+\.[0-9]+([.-][A-Za-z0-9]+)?$'or p_source_manifest_hash!~'^[0-9a-f]{64}$'or jsonb_typeof(p_findings)<>'array'or jsonb_array_length(p_findings)=0 or length(coalesce(p_idempotency_key,''))not between 8 and 200 then raise exception'INVALID_CATALOG_REVIEW_FINDINGS'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('catalog_version',p_catalog_version,'manifest_hash',p_source_manifest_hash,'findings',p_findings));perform pg_advisory_xact_lock(hashtextextended('catalog-review:'||p_idempotency_key,0));select*into prior from private.catalog_review_command_keys where idempotency_key=p_idempotency_key;if found then if prior.request_hash<>h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;return prior.response_body;end if;insert into private.catalog_review_command_keys(idempotency_key,request_hash,created_by)values(p_idempotency_key,h,a);for x in select value from jsonb_array_elements(p_findings)loop if not(x?&array['code','count','samples'])or x->>'code'not in('DUPLICATE_QUESTION_ID','DUPLICATE_SEMANTIC_QUESTION','QUESTION_WITHOUT_SERVICE','BROKEN_JSON_RULE','ANOMALY_WITHOUT_RECOMMENDATION','RECOMMENDATION_WITHOUT_OPPORTUNITY','SERVICE_WITHOUT_QUOTE_FORM','ARABIC_TRANSLATION_MISSING','EXPERT_REVIEW_REQUIRED')or coalesce((x->>'count')::bigint,0)<=0 or jsonb_typeof(x->'samples')<>'array'or jsonb_array_length(x->'samples')>10 then raise exception'INVALID_CATALOG_REVIEW_FINDING'using errcode='22023';end if;insert into public.catalog_content_review_findings(audit_run_id,finding_code,severity,finding_count,sample_references,review_status,catalog_version,source_manifest_hash,recorded_by,recorded_by_actor_type)values(run_id,x->>'code',case when x->>'code'in('ARABIC_TRANSLATION_MISSING','EXPERT_REVIEW_REQUIRED','BROKEN_JSON_RULE','QUESTION_WITHOUT_SERVICE','SERVICE_WITHOUT_QUOTE_FORM')then'BLOCKING'else'WARNING'end,(x->>'count')::bigint,array(select jsonb_array_elements_text(x->'samples')),'CONTENT_REVIEW_REQUIRED',p_catalog_version,p_source_manifest_hash,a,case when service_call then'SERVICE'else'USER'end);n:=n+1;end loop;r:=jsonb_build_object('outcome','CONTENT_REVIEW_REQUIRED','audit_run_id',run_id,'finding_types',n,'catalog_version',p_catalog_version);update private.catalog_review_command_keys set response_body=r,completed_at=clock_timestamp()where idempotency_key=p_idempotency_key;insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(null,a,case when service_call then'SERVICE'else'USER'end,'catalog.content_review.persisted','catalog_review',run_id::text,p_correlation_id,jsonb_build_object('catalog_version',p_catalog_version,'finding_types',n,'manifest_hash',p_source_manifest_hash),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(null,'catalog_review',run_id::text,'CatalogContentReviewRequiredV1',p_correlation_id,r,p_idempotency_key);return r;exception when invalid_text_representation then raise exception'INVALID_CATALOG_REVIEW_FINDING'using errcode='22023';end$$;
revoke all on function public.record_catalog_content_review_findings_v41(text,text,jsonb,text,uuid)from public,anon,authenticated,service_role;
