create function public.record_contract_lifecycle_event_v41(p_contract_id uuid,p_contract_version_id uuid,p_event_type text,p_from_status text,p_to_status text,p_reason text,p_evidence_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();c public.contracts%rowtype;h text;cached jsonb;r jsonb;x bigint;begin select*into c from public.contracts where id=p_contract_id;if a is null or not found or not(private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],a))then raise exception'CONTRACT_LIFECYCLE_EVENT_DENIED'using errcode='42501';end if;if not exists(select 1 from public.contract_versions v where v.id=p_contract_version_id and v.contract_id=c.id)or p_event_type not in('EFFECTIVE','RENEWAL_NOTICE','RENEWED','SUSPENDED','RESUMED','EXPIRED','TERMINATION_NOTICE','TERMINATED','LEGAL_HOLD_APPLIED','AMENDMENT_REQUIRED')or length(btrim(coalesce(p_to_status,'')))<2 or length(btrim(coalesce(p_reason,'')))<3 or p_evidence_hash!~'^[0-9a-f]{64}$'then raise exception'INVALID_CONTRACT_LIFECYCLE_EVENT'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('contract',c.id,'contract_version',p_contract_version_id,'event_type',p_event_type,'from_status',p_from_status,'to_status',p_to_status,'reason',p_reason,'evidence_hash',p_evidence_hash));cached:=private.begin_contract_command(c.client_organization_id,'contract.lifecycle.event.'||c.id::text,p_idempotency_key,h,a);if cached is not null then return cached;end if;insert into public.contract_lifecycle_events(contract_id,contract_version_id,event_type,from_status,to_status,reason,evidence_hash,actor_user_id,correlation_id)values(c.id,p_contract_version_id,p_event_type,p_from_status,p_to_status,p_reason,p_evidence_hash,a,p_correlation_id)returning id into x;r:=jsonb_build_object('outcome','CONTRACT_LIFECYCLE_EVENT_RECORDED','contract_id',c.id,'contract_version_id',p_contract_version_id,'event_id',x,'event_type',p_event_type);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,a,'USER','contract.lifecycle.event_recorded','contract',c.id::text,p_correlation_id,jsonb_build_object('event_id',x,'event_type',p_event_type,'to_status',p_to_status),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'contract',c.id::text,'ContractLifecycleEventRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(c.client_organization_id,'contract.lifecycle.event.'||c.id::text,p_idempotency_key,r);return r;end$$;
revoke all on function public.record_contract_lifecycle_event_v41(uuid,uuid,text,text,text,text,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.record_contract_lifecycle_event_v41(uuid,uuid,text,text,text,text,text,text,uuid)to authenticated;
